function CommonMicStateNode:AddListener()
    self.eventVoiceStateChanged = Events.AddListener(Constants.EventNames.VOICE_ROOM_MEMBERS, Bind(self, self.OnVoiceStateChanged))
    self.eventVoiceEnterRoom = Events.AddListener(Constants.EventNames.VOICE_ENTER_ROOM, Bind(self, self.OnVoiceEnterRoom))
    self.eventVoiceEvent = Events.AddListener(Constants.EventNames.VOICE_EVENT, Bind(self, self.OnVoiceEvent))
end

function CommonMicStateNode:RemoveListener()
    Events.RemoveListener(Constants.EventNames.VOICE_ROOM_MEMBERS, self.eventVoiceStateChanged)
    Events.RemoveListener(Constants.EventNames.VOICE_ENTER_ROOM, self.eventVoiceEnterRoom)
    Events.RemoveListener(Constants.EventNames.VOICE_EVENT, self.eventVoiceEvent)
end

--- 加入语音聊天房间结束回调
---@param code any
---@param errorInfo any
function CommonMicStateNode:OnVoiceEnterRoom(code, errorInfo)
    code = checkNumber(code)
    if code == 0
    or code == 1003 then
        -- if isNotNull(self.playerId) then
        --     self:RefreshBtnState()
        -- end
    else
        GameUtils.Toast(localize("加入语音聊天房间失败 code:_num_ info:_str_", {_num_ = code, _str_ = tostring(errorInfo)}))
    end
end

--- 语音状态变化回调
---@param eventID any
---@param count any
---@param identifiers any
function CommonMicStateNode:OnVoiceStateChanged(eventID, count, identifiers)
    local length = identifiers.Length
    for i = 0, length - 1, 1 do
        if checkNumber(identifiers[i]) == self.playerId then
            if eventID == 5 then
                self:StartAudioStream()
            elseif eventID == 6 then
                self:EndAudioStream()
            elseif eventID == 11 then
                self:SetMicOpenState(true)
            elseif eventID == 12 then
                self:SetMicOpenState(false)
            end
            print("[语音] 麦克风标识节点", checkNumber(identifiers[i]), eventID, count)
        end
    end
end

--- 语音事件
---@param type any
---@param subType any
---@param data any
function CommonMicStateNode:OnVoiceEvent(type, subType, data)
    -- print("[语音] 语音事件", type, subType, data)
    xTry(function()
        data = table.deserialize(data)
    end)
    if type == 6000 and subType == 6 then
        if isNotNull(data) and isNotNull(data.Result) and data.Result == 0 then     -- 请求成功
            if isNotNull(data.isACK) and data.isACK == true     -- 是应答消息
            and isNotNull(data.ReceiverID) and checkNumber(data.ReceiverID) == self.playerId then       -- 是请求的这个玩家
                -- 请求指定玩家的麦克风状态时的回复事件
                if isNotNull(data.OperateValue) then
                    self:SetMicOpenState(data.OperateValue)
                    -- print("[语音] 返回麦克风状态", self.playerId, data.OperateValue)
                end
            end
        end
    end
end

function CommonMicStateNode:SetPlayerId(playerId)
    self.playerId = playerId
end

function CommonMicStateNode:SetMicOpenState(boolean)
    KTool.SetActive(self.RT_CloseIcon, not boolean)
    
    if not boolean then
        self:EndAudioStream()
    end

    self.openState = boolean
end

function CommonMicStateNode:StartAudioStream()
    if isNotNull(self.openState) and self.openState == false then
        return
    end
    self.Animation_MicState:Stop()
    self.Animation_MicState:Play(AnimationHasAudioStream)
end

function CommonMicStateNode:EndAudioStream()
    if isNotNull(self.openState) and self.openState == false then
        return
    end
    self.Animation_MicState:Stop()
    self.Animation_MicState:Play(AnimationEndAudioStream)
end

return CommonMicStateNode